path = str(value or '').strip()
if not path:
	return []
import re
try:
	results = system.tag.browse(path, {'tagType': 'UdtInstance'}).getResults()
except:
	return []
cands = []
for r in results:
	try:
		cands.append((str(r['name']), str(r['fullPath'])))
	except:
		pass
if not cands:
	return []
qvs = system.tag.readBlocking([p + '.typeId' for n, p in cands])
names = [n for (n, p), qv in zip(cands, qvs) if str(qv.value or '').split(']')[-1].lower() == 'devices/pump']
names.sort(key=lambda s: [int(t) if t.isdigit() else t.lower() for t in re.split(r'(\d+)', s)])
return names

tagPath = ''
try:
	tagPath = str(self.view.params.tagPath or '')
except:
	pass
view_name = self.view.id.split('@')[0]
items = []
if value:
	logged = tagPath if tagPath.strip() else 'No TagPath: ' + view_name.split('/')[-1]
	items.append({
		"text": 'Ticket Logger',
		"icon": {"path": 'material/info', "color": "--neutral-80", "style": {}},
		"style": {"classes": "bg-component Fonts/Value", "height": 24, "width": 170},
		"type": "message",
		"children": [],
		"link": {"url": "", "target": "self"},
		"method": {"name": "", "params": {}},
		"message": {"type": 'ticketLog', "payload": {'tagPath': logged, 'viewName': view_name, 'sender': self.view.id}, "scope": 'page'}
	})
return items
